import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"周易尚氏学 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"周易尚氏学 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"zh/classics/shangshi/034.md","filePath":"zh/classics/shangshi/034.md"}'),s={name:"zh/classics/shangshi/034.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><p>归藏曰革。李过曰。牢（上草）者劳也。以万物劳于坎也。黄宗炎曰。物莫劳于牛。故从牛。按说文牢（上草）驳牛也。坤为牛。阳人坤中。色不纯。故曰牢（上草）。而牛为物之最劳者。故取于驳牛。周易名坎。则取于陷险二义。上耳坎故曰习。罗汝怀云。习当为折（左　）。礼玉藻帛为折（左　）。注衣有表裹而无着也。急就篇注。折（左　）谓重衣。皆重复之义。而折（左　）又假袭。礼锡袭。书卜不袭吉。故习当作袭。象曰。重险。象曰水洊至。即释习坎之义。自注有便习之说。后儒多从之。夫谙练于行事。此事理之常。岂有诸练于行险者哉。按罗说是也。彖传象传。皆有明释。王注及正义。诂为便习。此所以有野文之讥也孚。信也。有孚谓二五居中。遇阴。阳孚于上下阴也。旧解不知孚之故。在阳遇阴。故说皆不当。坎为心。亨通也。心亨亦谓二五。传所谓刚中也。行有尚则专谓五。五往外得尊位。故曰有尚。曰有功。</p><p>彖曰。习坎。重险也。水流而不盈。行险而不失其信。维心亨。乃以刚中也。行有尚。往有功也。天险。不可升也。地险。山川丘陵也。王公设险以守其国。险之时用大矣哉。</p><p>水流若盈。则非坎矣。既曰坎则不盈也。坎为失。为信。阳居中。故不失其信。五天位。居坎中。故曰天险。艮止故不可升。二地位。居坎中。故曰地险。艮为山为丘陵。坎为川。故曰山川丘陵也。震为王公。艮为国。为守。为时。为天。</p><p>象曰。水洊至。习坎。君子以常德行。习教事。</p><p>洊。再也。重坎故曰再至。艮为君子。震为德行为言。故曰教。习则教不巳。而德行有常矣。</p><p>初六。习坎入于坎窞。凶。</p><p>说文焰（左无上穴）坎中更有坎。王肃云。坎底也。字林云。坎中小坎。一曰旁人。案王肃说是也。初居坎之最下。故人于坎底。</p><h3 id="象曰。习坎入坎。失道凶也。" tabindex="-1">象曰。习坎入坎。失道凶也。 <a class="header-anchor" href="#象曰。习坎入坎。失道凶也。" aria-label="Permalink to “象曰。习坎入坎。失道凶也。”">​</a></h3><p>震为大涂。故曰道。初于震无应。故曰失道凶。</p><p>九二。坎有险。求小得。</p><p>二失位。故有险。阴为小。二居中。孚于上下阴。故曰求小得。</p><h3 id="象曰。求小得。未出中也。" tabindex="-1">象曰。求小得。未出中也。 <a class="header-anchor" href="#象曰。求小得。未出中也。" aria-label="Permalink to “象曰。求小得。未出中也。”">​</a></h3><p>象曰未出中。言五无应。故曰未出。有应则上升五而当位。所得大矣。</p><p>六三。来之坎坎。检从郑向本且枕。入于坎窞。勿用。</p><p>三居上下坎之间。来内为坎。之外亦坎。故曰来之坎坎。孟子狗彘食人食而不知检。赵歧云检敛也。又释名云。枕检也。所以检项也。然则枕与检义同。检且枕。仍承来之坎坎言。言内外俱受检制。既检且枕。仍与初交之人坎焰（左无上穴）同。夫前检后枕。来往既陷于险境。其不能用也必矣。故曰勿用。</p><h3 id="象曰。来之坎坎。终无功也。" tabindex="-1">象曰。来之坎坎。终无功也。 <a class="header-anchor" href="#象曰。来之坎坎。终无功也。" aria-label="Permalink to “象曰。来之坎坎。终无功也。”">​</a></h3><p>勿用故曰无功。艮为枕。易林需之大壮云。婚姻配合。同枕共牢。大壮通观。以艮为枕。坤众故同枕。</p><p>六四。樽酒。簋贰用岳。纳约自牖。终无咎。</p><p>坎为酒。震为尊。故曰尊酒。震为墓。簋祭器。以盛黍稷。中交正覆震。故曰簋贰。贰二同。曲礼虽不贰辞。注贰谓重骰（？）。此簋贰与损之二簋同。击说文瓦器。簋贰用击者。言用瓦簋。周礼施（右下瓦）人为簋。疏祭宗庙用木簋。今用瓦。祭天地尚质。器用陶匏。郊特牲亦云。器用陶匏。象天地之性。王夫之谓缶瓦也。与礼经合。得其义矣。约神约也。周礼秋官司约。掌六约。治神之约为上。治民之约次之。爻辞言尊簋。则祭神也。故知此约为神约。注神约命祀郊社群望及祖宗也。汉书高帝纪。约先人关者。注约要也。吕览淫辞。秦赵相与约。注约盟也。艮为牖。震为言。故曰纳约自牖。言诏明神而要誓。荐其盟祝之载辞于牖下也。又春官祖祝作盟祖之载辞。以叙国之信用。坎为信。故要誓于神也。承阳当位。故无咎。艮为终。故曰终无咎。酒击牖咎为韵。</p><h3 id="象曰。樽酒簋贰。刚柔际也。" tabindex="-1">象曰。樽酒簋贰。刚柔际也。 <a class="header-anchor" href="#象曰。樽酒簋贰。刚柔际也。" aria-label="Permalink to “象曰。樽酒簋贰。刚柔际也。”">​</a></h3><p>四承阳故曰刚柔际。际说文会也。</p><p>九五。坎不盈。只既平。无咎。</p><p>坎不盈。义见前。只京虞作提（左　）。曰安也。郑云当作坻。小丘也。按易字不能定者。当定之以象。郑于复卦无只侮。训只为病。兹又训为坻诚以坎不盈。与只既平为对文。则只为实字无疑。又五为艮主爻。艮山故曰抵。而坻与氏通。说文。氏巴蜀名山岸协之堆。旁者（上竹）欲落惰（左土？）者。曰氏。氏崩声闻数百里。扬雄赋晌若氏贵（左阜）。而文选解嘲作坻贵（左阜）。应劭云。天水有大　名曰陇坻。韦昭云。低音若是理之是。是坻与氏通。俞樾云。只既平。即氏贵（左阜）之氏。氏贵（左阜）即平矣。古本易盖止作氏既乎。后人误加示耳。案郑诂为坻。盖即疑只为氏。俞说正与郑合。而韦昭音坻为是。由是证只坻提音皆由氏得。从氏者误也。王引之谓郑作宛在水中低之批为误。岂知郑并未作抵。坻毛传云小诸。释水云。小洲曰渚。兹曰小丘明非渚也。以郑作低与解嘲同。与说文同也。不然郑岂不知仍诂为病。使前后一律哉。坎为平。故曰抵既平。坎不盈为一事。坻既平又为一事。上下对文。诂只为安者固非。仍诂为病。于象虽合。于义未安也。</p><h3 id="象曰。坎不盈。中未光大也。" tabindex="-1">象曰。坎不盈。中未光大也。 <a class="header-anchor" href="#象曰。坎不盈。中未光大也。" aria-label="Permalink to “象曰。坎不盈。中未光大也。”">​</a></h3><p>阳陷阴中。虽得中而未光大。</p><p>系用徽纆，寘于丛棘，三岁不得，凶。</p><p>刘表云。三股为徽。两胎为墨（左丝）。皆索名。以系缚罪人。虞翻云徽墨黑索也。徽墨（左丝）之象。虞用卦变。以观巽为绳。非也。盖坎为矫揉（左车）。物之能矫揉（左车）者。莫过于绳。故以徽墨（左丝）取象。坎为棘。上坎下坎。故曰丛棘。真（上？）示通。周礼朝士郑司农注及毂（左下禾）梁宣二年范宁注引。皆作示于丛棘。而诗鹿呜示我周行。郑则云示当作真（上？）。真（上？）置也真（上？）于丛棘。旧解皆谓以黑索系罪人。置于狱。或议于九棘之下也。三岁不得。言三年不得出也。茹敦和云。坎为三岁。</p><h3 id="象曰。上六失道。凶三岁也。" tabindex="-1">象曰。上六失道。凶三岁也。 <a class="header-anchor" href="#象曰。上六失道。凶三岁也。" aria-label="Permalink to “象曰。上六失道。凶三岁也。”">​</a></h3><p>上六应在三。三震为道。乃三不应上。故曰失道。</p><p>案上以丛棘为狱者。虞说也。虞谓狱外种棘。张惠言以不知所本而疑之矣。以周礼秋官朝士为本。使公卿议于九棘之下而定罪者。郑说也。然不曰九棘。而曰丛棘。文王演易之时仍殷制。殷是否有三槐九棘之制不可知。则亦可疑也。况爻词曰三岁不得。不得者不能遂其愿也。象曰。上六失道。失道者。言所为不当也。不当故不得。于人狱词意皆不合。按列子说符篇。臣有所与。共担墨（左丝）薪菜者。曰九方皋。是徽墨（左丝）可以约薪菜。扬雄酒箴云。子犹瓶矣。居井之湄。不得左右。牵于墨（左丝）徽。是徽墨（左丝）可为井索。胡为必束缚罪人。若以丛棘为疑。诗云。园有棘。其实之食。又云墓门有棘。斧以斯之。是棘常生于墓门及园囿。羽猎赋。斩丛棘。夷野草。吴志诸葛格（左　）传。升山赴险。抵突丛棘。是丛棘常生于山林。安在必为狱。故易林需之坎云。凿井求玉。非卞氏宝。名因身辱。劳无所得。上二句谓所施不得地。释真（上？）于丛棘。及失道之义也。下二句谓徒劳无功。释真（上？）于业棘。三岁不得之义也。依易林此释。似言徽墨（左丝）所以系物。然施于丛棘。则权权刺激。难于施设。故久不得。不得之故。则由于所真（上？）失道也。如是则不得与失道之故。与上文皆协洽矣。徽墨（左丝）皆绳索名耳。系物之用甚多。必谓专系罪人。无及执乎。</p>',31)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
